payload = base64.b64encode((root/'host/vision/nsh_console.py').read_bytes()).decode()
code = 'LIVE=%r\nPAYLOAD=%r\n' % (live, payload) + r'''
import base64,json,os,pathlib,subprocess,time
project=pathlib.Path('/home/swl/openvela/work/velavision-project')
root=project/LIVE
assert not root.exists(),'Existing console session: inspect, never duplicate'
assert subprocess.run(['fuser','/dev/ttyUSB0'],capture_output=True).returncode==1,'UART already owned'
identity=subprocess.check_output(['udevadm','info','--query=property','--name=/dev/ttyUSB0'],text=True)
assert 'ID_VENDOR_ID=1a86' in identity and 'ID_MODEL_ID=7523' in identity
root.mkdir(parents=True)
script=root/'nsh_console.py';script.write_bytes(base64.b64decode(PAYLOAD))
