        require(0 <= time.time() - receipt['observed_at'] < PROOF_MAX_AGE, 'Stop receipt stale')
    hold = receipts[0]
    require(0 <= hold['offset'] <= len(raw), 'Invalid hold log offset')
    tail = raw[hold['offset']:]
    # Same-mode hold is idempotent: it prints requested=0 but does not advance
    # the pipeline revision or print another applied ACK.
    clean = clean_telemetry(raw)
    clean_tail = clean_telemetry(tail)
    require(re.search(rb'(?:^|\n)VOICE MODE requested=0 result=0\r?\n', clean_tail), 'Missing fresh requested hold ACK')
    applied = list(re.finditer(rb'VOICE MODE applied=(-?\d+) result=(-?\d+)\r?\n', clean))
    require(applied and applied[-1].group(1, 2) == (b'0', b'0'), 'No successful existing applied hold')
    require(all(m.group(1, 2) == (b'0', b'0') for m in applied), 'Session contains non-held/failed applied mode')
    require(len(re.findall(rb'TRACK q=\d+ s=4[^\r\n]*?tx=0\b', tail)) >= 4, 'Missing post-hold samples')
    display = receipts[1]['output']
    require('dma_stopped=1 lease=0' in display and 'stop_stage=9 stop_error=0' in display, 'Display stop not proved')
    require(b'K7 PANEL stop_requested' in tail and b'camera_unchanged=1' in tail, 'Missing paneloff receipt')
    return {'hold': digest(args.hold), 'display': digest(args.display),
            'serial_prefix_size': len(raw), 'serial_prefix_sha256': hashlib.sha256(raw).hexdigest()}


def owner_release(args):
    state = json.loads((args.serial_root / 'state.json').read_text())
    require(state['owner_pid'] == args.owner_pid and state['port'] == '/dev/ttyUSB0', 'Owner identity mismatch')
    require(all(x['status'] in ('sent', 'rejected') for x in state['commands']), 'Pending console transmission')
    known = {x['request'] for x in state['commands']}
    require(all(p.name in known for p in (args.serial_root / 'commands').glob('*.json')), 'Unprocessed request')
