          {i+=strlen(marks[k]);skip=1;break;}
      if(skip)continue;
      if(used==sizeof(normalized)-1)return K7_VOICE_NONE;
      normalized[used++]=(ch>='A' && ch<='Z')?(char)(ch-'A'+'a'):text[i];i++;
