[CmdletBinding()]
param([ValidateSet('Check','Read')][string]$Mode='Check',
 [Parameter(Mandatory=$true)][string]$Manifest,
 [Parameter(Mandatory=$true)][string]$Image)
$ErrorActionPreference='Stop'
$backupMode=$Mode
$backupRoot=Split-Path $PSScriptRoot
$backupPython='python'
$backupPlanText=& $backupPython (Join-Path $PSScriptRoot 'prepare_private_boot_backup.py') --check --manifest $Manifest --image $Image
if($LASTEXITCODE){throw 'Offline candidate validation failed'}
$backupPlan=($backupPlanText -join "`n" | ConvertFrom-Json).plan
if($backupMode -eq 'Check'){Write-Output ($backupPlan | ConvertTo-Json);return}
. (Join-Path $PSScriptRoot 'k7_native_session.ps1')
. (Join-Path $PSScriptRoot 'k7_native_md_parser.ps1')
$nativeOut=Join-Path $backupRoot ('private/persistent-backups/native-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ'))
$null=New-Item -ItemType Directory -Path $nativeOut
$nativeReport=[ordered]@{status='started';commands=@();storage_written=$false;reset_sent=$false;automatic_retry=$false;old_prefix_crc_verified=$false;plan=$backupPlan}
$nativeSerial=$null;$nativeLog=$null
function Read-BackupRange([uint64]$Address,[uint64]$Lba,[int]$Count) {
 $reply=Command-Native ('mmc read '+$Address.ToString('x')+' '+$Lba.ToString('x')+' '+$Count.ToString('x'))
 if($reply -notmatch ($Count.ToString()+' blocks read: OK')){throw 'MMC read incomplete'}
}
function Dump-Backup([uint64]$Address,[int]$Length,[string]$Name,[switch]$Gpt) {
 $path=Join-Path $nativeOut ($Name+'.bin')
 $file=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
 try {
  for($offset=0;$offset -lt $Length;) {
   $chunk=[Math]::Min(16384,$Length-$offset);$at=$Address+[uint64]$offset
   $cmd='md.l '+$at.ToString('x')+' '+([int]($chunk/4)).ToString('x')
   $reply=Command-Native $cmd
   $bytes=[VelaVision.NativeMdDecoder]::Decode($reply,$at,$chunk,$cmd)
   $file.Write($bytes,0,$bytes.Length);$offset+=$chunk
  }
 } finally {$file.Dispose()}
 $argsList=@((Join-Path $PSScriptRoot 'finish_private_boot_backup.py'),'--file',$path)
 if($Gpt){$argsList+='--gpt'}
 $metadata=& $backupPython @argsList
 if($LASTEXITCODE){throw 'Dump/GPT validation failed'}
 $meta=($metadata -join "`n") | ConvertFrom-Json
 $null=Require-CrcNative $Address.ToString('x') $Length.ToString('x') $meta.crc32
}
try {
 Save-Native
 $inv=Get-K7Inventory
 $inv | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath (Join-Path $nativeOut 'inventory.json') -Encoding UTF8
 if($inv.assessment.serial_state -ne 'enumerated_not_opened' -or @($inv.assessment.serial_ports).Count -ne 1){throw 'Exclusive CH340 inventory required'}
 $nativeSerial=New-Object IO.Ports.SerialPort($inv.assessment.serial_ports[0],1500000,[IO.Ports.Parity]::None,8,[IO.Ports.StopBits]::One)
 $nativeSerial.DtrEnable=$false;$nativeSerial.RtsEnable=$false;$nativeSerial.Handshake=[IO.Ports.Handshake]::None
 $nativeSerial.ReadTimeout=40;$nativeSerial.WriteTimeout=1000;$nativeSerial.ReadBufferSize=1048576
 $nativeLog=[IO.File]::Open((Join-Path $nativeOut 'console.raw'),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
 $nativeSerial.Open()
 $drain=[Diagnostics.Stopwatch]::StartNew();$buffer=New-Object byte[] 32768
 while($nativeSerial.BytesToRead -gt 0){if($drain.Elapsed.TotalSeconds -gt 2){throw 'Console continuously active'};$n=$nativeSerial.Read($buffer,0,$buffer.Length);$nativeLog.Write($buffer,0,$n)}
 $nativeLog.Flush();$nativeSerial.Write([byte[]]@(3),0,1);$null=Read-Native '(?m)(?:^|\n)=>\s*$' 10
 if((Command-Native 'version') -notmatch '(?m)^U-Boot 2017\.09\b'){throw 'Fresh U-Boot version mismatch'}
 if((Command-Native 'mmc dev 0') -notmatch 'current device'){throw 'MMC selection failed'}
 Read-BackupRange 0x47800000 0 34;Dump-Backup 0x47800000 17408 'gpt-primary' -Gpt
 Read-BackupRange 0x47000000 51200 11164
 $null=Require-CrcNative '47000000' '573800' '6ec5c64e';$nativeReport.old_prefix_crc_verified=$true
 foreach($name in @('extension','extension-recheck')) {
  Read-BackupRange 0x47600000 62364 ([int]($backupPlan.extension_bytes/512))
  Dump-Backup 0x47600000 $backupPlan.extension_bytes $name
 }
 if((Get-FileHash (Join-Path $nativeOut 'extension.bin')).Hash -ne (Get-FileHash (Join-Path $nativeOut 'extension-recheck.bin')).Hash){throw 'Extension reads differ'}
 Read-BackupRange 0x47600000 ([uint64]$backupPlan.last_lba+1) 1;Dump-Backup 0x47600000 512 'adjacent-sector'
 $nativeReport.status='pass';Save-Native
 Copy-Item -LiteralPath (Join-Path $nativeOut 'result.json') -Destination (Join-Path $nativeOut 'progress.json')
 & $backupPython (Join-Path $PSScriptRoot 'finish_private_boot_backup.py') --manifest $Manifest --image $Image --directory $nativeOut
 if($LASTEXITCODE){throw 'Offline rollback finalization failed'}
} catch {$nativeReport.status='failed';$nativeReport.error=$_.Exception.Message;throw}
finally {
 if($nativeSerial){if($nativeSerial.IsOpen){$nativeSerial.Close()};$nativeSerial.Dispose()}
 if($nativeLog){$nativeLog.Dispose()}
 $nativeReport.ended_at=[DateTime]::UtcNow.ToString('o');Save-Native
 Write-Output ('Evidence: '+$nativeOut)
}
"}

{"chunk_id":"ce9156","wall_time_seconds":0.124078,"exit_code":0,"original_token_count":6765,"output":"## node_repl + @oai/sky

- Use `node_repl` JavaScript for all Computer Use actions.
- The `node_repl` state persists across calls. Store cross-cell values on `globalThis`; top-level `const` and `let` names cannot be redeclared by later retries.
- For text output, call `nodeRepl.write(...)` with a string. Use `JSON.stringify(...)` for objects.

## Workflow

### Initialize target selection

Run the Initialize setup cell from `SKILL.md` first. Then list apps and choose the target from returned app and window objects:

```js
globalThis.apps = await sky.list_apps();
nodeRepl.write(JSON.stringify(apps, null, 2));
```

Never reconstruct an app or window from guessed fields. Do not call `get_window`, `activate_window`, or any input method until selection has produced exactly one returned window.

```js
{
  function escapeRegExp(value) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function returnedWindowSummary(window) {
    return {
      id: window.id,
      app: window.app,
      title: window.title,
    };
  }

  function requireUniqueWindow(windows, label) {
    if (windows.length !== 1) {
      nodeRepl.write(
        `Returned candidate windows:\n${JSON.stringify(windows.map(returnedWindowSummary), null, 2)}`,
      );
      throw new Error(`Expected exactly one target window for ${label}; found ${windows.length}`);
    }
    return windows[0];
  }

  globalThis.apps = await sky.list_apps();
  globalThis.targetApp = apps.find((app) => app.id === "<app id>");
  if (!targetApp) throw new Error("Target app was not returned by list_apps");
  const targetAppId = targetApp.id;

  if (targetApp.windows.length === 0) {
    await sky.launch_app({ app: targetApp.id });
    globalThis.apps = await sky.list_apps();
    globalThis.targetApp = apps.find((app) => app.id === targetAppId);
  }
  if (!targetApp?.windows.length) {
    throw new Error("Target app did not expose a window after launch");
  }

  const windowTitleHint = "<optional exact window title>";
  const candidateWindows =
    windowTitleHint === "<optional exact window title>"
      ? targetApp.windows
      : targetApp.windows.filter((window) =>
          new RegExp(`^${escapeRegExp(windowTitleHint)}$`, "i").test(window.title ?? ""),
        );
  const returnedWindow = requireUniqueWindow(candidateWindows, targetApp.id);

  globalThis.targetWindow = await sky.get_window({
    id: returnedWindow.id,
    app: returnedWindow.app,
  });
  await sky.activate_window({ window: targetWindow });
  globalThis.state = await sky.get_window_state({ window: targetWindow });
  globalThis.targetWindow = state.window;
}
```

Use `list_windows()` when inspecting currently open windows or recovering a known running app. If the intended app is absent from `list_apps`, launch it with an explicit `.exe` path or `.exe` process identifier, refresh `list_apps()` or `list_windows()`, filter to the intended returned windows, and stop unless the filtered list has exactly one window. Escape Windows path backslashes in JavaScript strings, for example `await sky.launch_app({ app: "C:\\Users\\me\\build\\MyApp.exe" });`.

### Act and refresh

Use a two-cell loop for state-derived inputs: observe and stop, inspect the result, then perform exactly one action and refresh immediately. Element indexes, screenshot IDs, and coordinates are valid only for the observation that produced them. Interleaving or retry requires re-observation.

Accessibility path, cell 1: observe and inspect.

```js
globalThis.state = await sky.get_window_state({
  window: targetWindow,
  include_screenshot: false,
  include_text: true,
});
globalThis.targetWindow = state.window;
nodeRepl.write(String(state.accessibility?.tree || state.accessibility?.document_text || ""));
```

Stop here and inspect the emitted tree before choosing an index.

Accessibility path, cell 2: one action and refresh.

```js
{
  const observation = globalThis.state;
  if (observation?.accessibility == null) {
    throw new Error("No accessibility observation; reobserve before acting");
  }
  const elementIndex = 12; // Replace with one index from the printed accessibility tree.
  globalThis.state = null;
  try {
    await sky.click({ window: observation.window, element_index: elementIndex });
